package mcpserver

// accountExtraTools are the legacy getAccount, setAccountAmount, getAccountFormula/setAccountFormula,
// atomCreateTransaction, saveAccountActors (account tags and triggers) and
// getDataFieldActorsByActor/saveDataFieldActorsByActor on public methods. Every update of a set
// replaces the whole set: read it first and send what to keep. getChildAccounts is not carried
// over: account trees were removed from the platform.
var accountExtraTools = []parityTool{
	{Name: "account_by_id_get", Method: "account_actor/by-id/get", Description: "Read one account row by its id (from a transaction, a formula source or a trigger) with its balance resolved; from (Unix ms) makes amount the turnover from then until to or now, to alone the balance at that moment; with meta, triggers, tags. Needs view on the actor and the pair."},
	{Name: "account_amount_set", Method: "account_actor/amount/update", Destructive: true, Description: "Set an account row's balance (id) to amount by recording the difference as a transaction: permanent and in its history (undo by setting the old value back); nothing is recorded when it already equals amount. A formula or statistical account is refused. Needs modify on the pair and, for a person, the transfers-management permission. Confirm with the user first."},
	{Name: "account_formula_get", Method: "account_actor/formula/get", Description: "Read an account row's formula (id): the text, the source accounts it reads with their balances and whether you may view them, and the value it evaluates to now (or the error)."},
	{Name: "account_formula_preview", Method: "account_actor/formula/preview", Description: "Check a formula on an account row (id) without saving it: ok and the value it would give now, or the first error (code such as formula.syntax, formula.cycle), warnings, and the functions the grammar accepts. A formula refers to source accounts by their ids. Run it before account_formula_set."},
	{Name: "account_formula_set", Method: "account_actor/formula/update", Destructive: true, Description: "Set, change or clear (empty formula) an account row's formula (id): the account then computes its balance from its sources and takes no transactions; one that has transactions cannot take a formula. A formula that does not validate is refused: check it with account_formula_preview. Needs modify on the pair and view on every source."},
	{Name: "atom_transaction_create", Method: "transaction/atom/create", Destructive: true, Description: "Post 1..20 transactions all-or-nothing (each as in transaction_create: accountId, amount, type, ref unique per account): e.g. a debit on one account and a credit on another in one step. Any refusal (access, a blocked or formula account, a repeated ref) stores nothing; a transaction past a limit is stored as declined without failing the others. Always send refs and confirm with the user first."},
	{Name: "account_tags_list", Method: "account/tags/list", Description: "List the tags (actors of the Tags template) an account pair (nameId, currencyId) is filed under."},
	{Name: "account_tag_add", Method: "account/tags/create", Description: "File an account pair (nameId, currencyId) under one more tag by its title: an existing tag of that name (case-insensitive) is reused, else one is created. Adds to the pair's tags; needs view on the pair."},
	{Name: "account_tags_set", Method: "account/tags/update", Destructive: true, Description: "Replace the whole set of tags (tag actor ids) an account pair (nameId, currencyId) is filed under; empty files it under none. It replaces others' tags too: read account_tags_list first and send every tag to keep. Needs modify on the pair."},
	{Name: "account_triggers_list", Method: "account/triggers/list", Description: "List the triggers (actors of the AccountTriggers template, amount or count kind) bound to an account pair (nameId, currencyId) as a whole; one actor's own account triggers are account_actor_triggers_list."},
	{Name: "account_triggers_set", Method: "account/triggers/update", Destructive: true, Description: "Replace the whole set of pair-level triggers (trigger actor ids of the amount or count kind) of an account pair (nameId, currencyId); empty unbinds them all. Read account_triggers_list first and send every trigger to keep. Needs modify on the pair."},
	{Name: "account_actor_triggers_list", Method: "account_actor/triggers/list", Description: "List the triggers bound to one actor's own account of a pair (actorId, nameId, currencyId), apart from the pair-level ones."},
	{Name: "account_actor_triggers_set", Method: "account_actor/triggers/update", Destructive: true, Description: "Replace the whole set of triggers (amount or count kind) bound to one actor's own account of a pair (actorId, nameId, currencyId); empty unbinds them all. Read account_actor_triggers_list first and send every trigger to keep. Needs view on the actor and modify on the pair."},
	{Name: "account_actor_tags_list", Method: "account_actor/tags/list", Description: "List the tag folders an actor's accounts are filed under, each with how many of its pairs it holds, plus the untagged bucket; a folder's actorId is the tag filter of accounts_list (untagged true for the bucket). One page per call (limit/offset)."},
	{Name: "account_actor_tags_count", Method: "account_actor/tags/count", Description: "Count the tag folders account_actor_tags_list returns, the untagged bucket included."},
	{Name: "actor_field_triggers_list", Method: "actor/field/triggers/list", Description: "List the data triggers (AccountTriggers actors of the data kind) bound to one data field (dataField, its id in the template) of an actor; they fire when that field's value changes."},
	{Name: "actor_field_triggers_set", Method: "actor/field/triggers/update", Destructive: true, Description: "Replace the whole set of data triggers (trigger actor ids of the data kind) bound to one data field of an actor; empty unbinds them all. Read actor_field_triggers_list first and send every trigger to keep. Needs view on the actor."},
}
